import { Handle, Position, useNode } from '@xyflow/react';
import './FiberDeviceNode.css';

const deviceIcons = {
  router: '🌐',
  switch: '🔌',
  olt: '📡',
  ont: '💻'
};

const deviceColors = {
  router: '#ef4444',
  switch: '#f59e0b',
  olt: '#10b981',
  ont: '#3b82f6'
};

export default function FiberDeviceNode({ data, selected, isDragging }) {
  const { id } = useNode();
  const icon = deviceIcons[data.type] || '📦';
  const color = deviceColors[data.type] || '#64748b';

  return (
    <div 
      className={`fiber-node ${selected ? 'selected' : ''} ${isDragging ? 'dragging' : ''} type-${data.type}`}
      style={{ 
        cursor: isDragging ? 'grabbing' : 'grab',
        // ✅ Prevent text selection during drag
        userSelect: 'none',
        WebkitUserSelect: 'none',
        MozUserSelect: 'none',
        msUserSelect: 'none'
      }}
      // ✅ Allow drag events to propagate to React Flow
      onDragStart={(e) => e.stopPropagation()}
      onDragEnd={(e) => e.stopPropagation()}
    >
      {/* Type indicator dot */}
      <div 
        style={{
          position: 'absolute',
          top: 8,
          right: 8,
          width: 8,
          height: 8,
          borderRadius: '50%',
          background: color,
          pointerEvents: 'none' // ✅ Don't block drag
        }}
      />
      
      {/* ✅ Header area - safe to drag from */}
      <div 
        className="node-drag-handle"
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          height: '24px',
          cursor: 'grab',
          zIndex: 1
        }}
      />
      
      <div className="node-icon" style={{ pointerEvents: 'none' }}>{icon}</div>
      <div className="node-header">{data.type.toUpperCase()}</div>
      
      <div className="node-details">
        <div className={`node-row ${!data.hostname ? 'value-empty' : ''}`}>
          <span>Host:</span>
          <strong>{data.hostname || '—'}</strong>
        </div>
        <div className={`node-row ${!data.ip ? 'value-empty' : ''}`}>
          <span>IP:</span>
          <strong>{data.ip || '—'}</strong>
        </div>
      </div>

      {/* Connection handles - pointerEvents none so they don't block node drag */}
      <Handle 
        type="target" 
        position={Position.Left} 
        style={{ 
          background: color, 
          borderColor: color,
          zIndex: 2,
          // ✅ Only enable pointer events when connecting, not dragging node
          pointerEvents: 'auto'
        }}
      />
      <Handle 
        type="source" 
        position={Position.Right} 
        style={{ 
          background: color, 
          borderColor: color,
          zIndex: 2,
          pointerEvents: 'auto'
        }}
      />
    </div>
  );
}
